<h1>قوانین پایه</h1><p class="notice">این قسمت مخصوص قوانین پایه حساب است. انتشار شرایط ضبط همچنان بسته است.</p><section class="card section"><h2>ساخت نسخه تغییرناپذیر جدید</h2><?= $this->start('/legal/create') ?><?= $this->field('title','عنوان نسخه') ?><label for="body">متن مصوب قوانین پایه</label><textarea id="body" name="body" maxlength="60000" required><?= $this->val('body') ?></textarea><button class="primary">ذخیره نسخه جدید بدون انتشار</button></form></section><div class="records section"><?php foreach($rows as $row): ?><article class="card"><h2>نسخه <?= $this->h($row['version_no']) ?>: <?= $this->h($row['title']) ?></h2><div class="bodytext"><?= $this->h($row['body']) ?></div><p class="small ltr">SHA-256: <?= $this->h($row['content_sha256']) ?></p><?php if(($current['id']??null)===$row['id']): ?><span class="tag">نسخه منتشرشده فعلی</span><?php else: ?><?= $this->start('/legal/publish') ?><input type="hidden" name="id" value="<?= $this->h($row['id']) ?>"><label class="row"><input type="checkbox" class="checkbox" required>انتشار همین نسخه را تأیید می‌کنم.</label><button class="secondary">انتشار این نسخه قوانین پایه</button></form><?php endif; ?></article><?php endforeach; ?></div>
